import pandas as pd


def clean(df):
    df = df.copy()
    # Convert numeric columns defensively (sample shows them as text)
    for col in ['Quantity', 'Price', 'Revenue']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # Remove exact duplicate rows (e.g., Order_ID 2006 appears twice)
    df = df.drop_duplicates().reset_index(drop=True)
    # Drop rows with missing Region (cannot be grouped)
    df = df.dropna(subset=['Region']).reset_index(drop=True)
    return df


def answer(df):
    result = {}
    grouped = df.groupby('Region')['Quantity'].sum()
    for region, qty in grouped.items():
        result[region] = int(qty)
    return result
